var i=`1252-doubles`;var n=`world-1252`;var t=`TT`;var r=`central-america-caribbean`;var o=8;var s=512;var l={en:`Doubles`,ua:`Даблс`};var d={en:`Doubles is a dish from Trinidad and Tobago featuring chickpeas, yellow onion, garlic, all-purpose flour. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Даблс, страва кухні країни Тринідад і Тобаго з такими основними складниками: нут, жовта цибуля, часник, пшеничне борошно універсальне. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Soak the dried beans in ample clean cold water for about 360 minutes, drain and discard the soaking water; cook fully in fresh water.`,ua:`Замочіть сухі бобові у достатній кількості чистої холодної води на приблизно 360 хвилин, злийте її й повністю зваріть у свіжій воді.`,t:[`soaking-legumes`],m:360,i:[[`chickpeas`,360,`g`],[`water`,850,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 75 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 75 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:75,i:[[`water`,850,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,130,`g`],[`garlic`,4,`clove`],[`curry-powder`,18,`g`],[`ground-cumin`,5,`g`]]},{en:`Knead a soft turmeric yeast dough and proof until puffy. Divide into small balls; the two fried bara breads must remain flexible, not crisp.`,ua:`Замісіть м’яке дріжджове тісто з куркумою й дайте йому піднятися. Розділіть на кульки: два смажені коржі бара мають залишатися гнучкими, а не хрусткими.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:45,i:[[`all-purpose-flour`,450,`g`],[`instant-yeast`,7,`g`],[`ground-turmeric`,4,`g`],[`water`,250,`ml`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 16 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 16 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:16,i:[[`canola-oil`,700,`ml`]]},{en:`Layer the warm chickpea curry between two soft fried bara breads for each portion, then add tart tamarind and coriander.`,ua:`На кожну порцію покладіть тепле карі з нуту між двома м’якими смаженими бара, додайте кислий тамаринд і кінзу.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`tamarind-concentrate`,45,`g`],[`cilantro`,20,`g`]]}];var m={slug:i,id:n,country:`TT`,region:r,servings:8,minutes:512,title:l,text:d,steps:u};export{t as country,m as default,n as id,s as minutes,r as region,o as servings,i as slug,u as steps,d as text,l as title};